<?php
/* Caminho: redes/suporte.php */
declare(strict_types=1);
const ARC_TOOLS_VERSION = '3.5.0';
require dirname(__DIR__).'/includes/bootstrap.php';
$pdo=arc_db();arc_ensure_user_schema($pdo);$networkId=(int)($_GET['network']??0);
if(!arc_is_user()){header('Location: '.arc_workspace_base_url().'index.php',true,303);exit;}
try{arc_support_access($pdo,$networkId,(int)arc_user_id());}catch(RuntimeException $e){http_response_code(403);exit('Rede não autorizada.');}
$arcSectionFile='suporte';require __DIR__.'/_base.php';require __DIR__.'/_topo.php';
$canSupportAdmin=in_array($teamRole,['owner','administrator'],true);
$tools=[['restart_readiness','Verificar reinicialização','stethoscope','Confere se o Windows precisa ser reiniciado, sem reiniciar o computador.']];
?>
<section class="arc-service arc-tools-page arc-support-page" aria-label="Suporte da rede"><div class="arc-support-mosaic" aria-label="Ações de suporte">
<button type="button" class="arc-tool-card" id="arc-agent-remote-view" <?=!in_array($teamRole,['owner','administrator','operator'],true)||!$selectedAgentId?'disabled':''?> aria-label="Acesso remoto web"><i class="fa fa-globe" aria-hidden="true"></i><strong>Acesso remoto web</strong></button>

<a class="arc-tool-card" href="api/download-support.php" aria-label="Instalar aplicativo de suporte"><i class="fa fa-download" aria-hidden="true"></i><strong>Baixar aplicativo de suporte</strong></a>

<button type="button" class="arc-tool-card" data-open-dialog="file-transfer" <?=!in_array($teamRole,['owner','administrator','operator'],true)||!$selectedAgentId?'disabled':''?>><i class="fa fa-exchange" aria-hidden="true"></i><strong>Enviar e receber arquivos</strong></button><?php foreach($tools as [$key,$label,$icon,$description]):?><button type="button" class="arc-tool-card" data-tool-command="<?=$key?>" aria-label="Verificar <?=arc_h($label)?>" title="<?=arc_h($description)?>" <?=!$canSupportAdmin||!$selectedAgentId?'disabled':''?>><i class="fa fa-<?=$icon?>" aria-hidden="true"></i><strong><?=arc_h($label)?></strong></button><?php endforeach;?><?php foreach(['power_shutdown'=>['Desligar computador','power-off']] as $power=>[$label,$icon]):?><button type="button" class="arc-tool-card" data-power-command="<?=$power?>" <?=$canSupportAdmin&&$selectedAgentId?'':'disabled'?>><i class="fa fa-<?=$icon?>" aria-hidden="true"></i><strong><?=$label?></strong></button><?php endforeach;?><button type="button" class="arc-tool-card" data-open-dialog="support-schedules" <?=$canSupportAdmin&&$selectedAgentId?'':'disabled'?>><i class="fa fa-calendar-check-o" aria-hidden="true"></i><strong>Agendar serviços</strong></button></div>
<dialog class="arc-service-dialog" id="power-confirm"><header class="arc-service-heading"><h2>Controle de energia</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p id="power-target"></p><p>Somente computadores com agente atualizado. A pessoa no computador deve autorizar. Servidores com modo sem monitor já habilitado aceitam a solicitação do gestor sem confirmação local. Salve seu trabalho antes de autorizar. O desligamento acontece 60 segundos após a autorização. Dispositivos sem agente não aceitam esta operação.</p><label class="arc-service-form">Senha da sua conta<input id="power-password" type="password" autocomplete="current-password"></label><button type="button" class="button primary" id="power-send">Confirmar solicitação</button></dialog>
<p id="tool-feedback" role="status"></p>
<dialog class="arc-service-dialog" id="tool-result"><header class="arc-service-heading"><h2 id="tool-title">Verificação</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p id="tool-result-state" role="status">Aguardando o computador…</p><div class="arc-tool-facts" id="tool-result-details"></div></dialog>
<dialog class="arc-service-dialog arc-files-dialog" id="file-transfer"><header class="arc-service-heading"><h2>Arquivos</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header>
<p>Envie para o computador selecionado ou peça um arquivo. Com confirmação local, a pessoa escolhe o arquivo ou destino. Sem monitor, proprietário e administrador usam Downloads/ArcollRecebidos para receber e Documentos/ArcollCompartilhados para enviar um único arquivo. Disponível por 24 horas.</p>
<form id="file-send-form" class="arc-service-form"><label>Arquivo<input type="file" name="file" id="file-source" required></label><div class="arc-service-actions"><button class="button primary" id="file-send" title="Enviar ao computador"><i class="fa fa-upload" aria-hidden="true"></i> Enviar</button><button type="button" class="button" id="file-receive" title="Pedir um arquivo do computador"><i class="fa fa-download" aria-hidden="true"></i> Receber</button></div></form>
<p id="file-feedback" role="status"></p><div id="file-list" class="arc-service-list" aria-label="Transferências recentes"></div></dialog>
<dialog class="arc-service-dialog arc-schedules-dialog" id="support-schedules"><header class="arc-service-heading"><h2>Agendar serviços</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header>
<p>Horários de Belém (UTC−3). O computador precisa estar conectado no horário. Horários perdidos não são executados depois. Ações de energia mantêm a autorização local ou o modo de servidor já habilitado.</p>
<form id="schedule-form" class="arc-service-form"><label>Serviço<select name="command" required><option value="" selected disabled>Escolha o serviço</option><?php foreach(arc_support_schedule_actions() as $command=>$label):?><option value="<?=$command?>"><?=$label?></option><?php endforeach;?></select></label><div class="arc-service-fields"><label>Início<input type="datetime-local" name="starts_at" value="<?=date('Y-m-d\TH:i',time()+300)?>" required></label><label>Repetir<select name="recurrence"><option value="once">Uma vez</option><option value="weekdays">Dias da semana</option><option value="interval">A cada intervalo</option></select></label><label>Fim do período (opcional)<input type="datetime-local" name="ends_at"></label><label data-schedule-interval hidden>Intervalo em minutos<input type="number" name="interval_minutes" min="15" max="10080" value="60"></label></div><fieldset data-schedule-days hidden><legend>Dias da semana</legend><div class="arc-schedule-weekdays"><?php foreach([1=>'Seg',2=>'Ter',3=>'Qua',4=>'Qui',5=>'Sex',6=>'Sáb',7=>'Dom'] as $day=>$label):?><label><input type="checkbox" name="weekdays" value="<?=$day?>"> <?=$label?></label><?php endforeach;?></div></fieldset>
<div data-schedule-power><label>Senha da sua conta<input type="password" name="password" autocomplete="current-password"></label><label class="arc-schedule-consent"><input type="checkbox" name="confirmed"> Confirmo a ação de energia no computador selecionado.</label></div><button type="submit" class="button primary"><i class="fa fa-calendar-plus-o" aria-hidden="true"></i> Agendar</button></form>
<p id="schedule-feedback" role="status"></p><h3>Agendamentos</h3><div id="schedule-list" class="arc-service-list"></div><details><summary>Histórico de execução</summary><div id="schedule-runs" class="arc-service-list"></div></details><p>Cancelar impede novas execuções. Uma ação já iniciada no Windows não é desfeita.</p></dialog>

</section>
<script>
(()=>{'use strict';const network=<?=json_encode($networkId)?>,csrf=<?=json_encode($csrf)?>,base=<?=json_encode(arc_workspace_base_url())?>;const dialog=document.getElementById('tool-result'),state=document.getElementById('tool-result-state'),facts=document.getElementById('tool-result-details'),feedback=document.getElementById('tool-feedback');let busy=false;
const plain=value=>window.arcPlainMessage?window.arcPlainMessage(value):String(value||'');
function fact(label,value){const item=document.createElement('div'),name=document.createElement('small'),data=document.createElement('strong');name.textContent=label;data.textContent=value;item.append(name,data);facts.append(item)}
function details(data){facts.replaceChildren();if(typeof data.restart_pending==='boolean')fact('Reinicialização',data.restart_pending?'Combine um horário para reiniciar':'Não há pedido do Windows');}
async function json(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Não foi possível verificar.');return j;}
let power=null;const powerDialog=document.getElementById('power-confirm');
document.querySelectorAll('[data-power-command]').forEach(button=>button.addEventListener('click',()=>{const select=document.getElementById('arc-agent-target');if(!select.value)return;power={command:button.dataset.powerCommand,agent:Number(select.value),label:button.textContent.trim()};document.getElementById('power-target').textContent=power.label+' · '+select.selectedOptions[0].textContent;document.getElementById('power-password').value='';powerDialog.showModal();}));
document.getElementById('power-send').addEventListener('click',async function(){if(!power||this.disabled)return;this.disabled=true;const request=power;try{const task=await json(base+'api/api.php?action=network-command',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({network_id:network,agent_id:request.agent,command:request.command,confirmed:true,password:document.getElementById('power-password').value})});powerDialog.close();document.dispatchEvent(new CustomEvent('arc:command-queued',{detail:{command_id:task.command_id,agent_id:request.agent,command:request.command}}));feedback.textContent='Solicitação enviada. Aguardando o computador.';}catch(e){feedback.textContent=plain(e.message);powerDialog.close();}finally{this.disabled=false;power=null;}});

const fileDialog=document.getElementById('file-transfer'),fileMessage=document.getElementById('file-feedback'),fileList=document.getElementById('file-list');let fileBusy=false,fileLimit=<?=arc_support_file_limit()?>;
const fileLabels={pending:'Aguardando o computador',ready:'Pronto para baixar',completed:'Concluído',declined:'Não autorizado no computador',failed:'Não foi possível concluir',expired:'Expirado'};
async function fileApi(action,options={}){return json(base+'api/support.php?action='+action,{headers:{'X-CSRF-Token':csrf},...options});}
async function loadFiles(){if(!fileDialog.open||fileBusy)return;try{const agent=Number(document.getElementById('arc-agent-target').value);const result=await fileApi('file-list&network='+network+'&agent='+agent);fileLimit=result.max_bytes;fileList.replaceChildren();for(const row of result.transfers){const article=document.createElement('article'),text=document.createElement('div'),name=document.createElement('strong'),state=document.createElement('small');name.textContent=row.filename||(row.direction==='from_agent'?'Arquivo solicitado':'Arquivo');const expired=new Date(row.expires_at.replace(' ','T')+'-03:00')<=new Date();const status=expired?'expired':row.status==='pending'&&['failed','expired'].includes(row.task_status)?row.task_status:row.status;state.textContent=(row.direction==='to_agent'?'Enviado · ':'Recebido · ')+(fileLabels[status]||'Em andamento')+(row.file_size?' · '+(row.file_size/1048576).toLocaleString('pt-BR',{maximumFractionDigits:2})+' MB':'');text.append(name,state);article.append(text);if(row.status==='ready'&&new Date(row.expires_at.replace(' ','T')+'-03:00')>new Date()){const link=document.createElement('a');link.className='arc-icon-action';link.href=base+'api/support.php?action=file-download&id='+row.id;link.setAttribute('aria-label','Baixar '+row.filename);link.title='Baixar arquivo';const icon=document.createElement('i');icon.className='fa fa-download';icon.setAttribute('aria-hidden','true');link.append(icon);article.append(link);}fileList.append(article);}if(!result.transfers.length)fileList.textContent='Nenhuma transferência ainda.';if(!fileMessage.textContent)fileMessage.textContent='Até '+(fileLimit/1048576).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MB por envio nesta hospedagem.';}catch(e){fileMessage.textContent=plain(e.message);}}
document.querySelector('[data-open-dialog="file-transfer"]').addEventListener('click',()=>setTimeout(loadFiles,0));setInterval(()=>{if(!document.hidden)loadFiles()},5000);
async function requestFile(action){if(fileBusy)return;const agent=Number(document.getElementById('arc-agent-target').value);if(!agent)return;const form=new FormData();form.set('network',network);form.set('agent',agent);if(action==='file-send'){const file=document.getElementById('file-source').files[0];if(!file)return;if(file.size>fileLimit){fileMessage.textContent='Escolha um arquivo menor que o limite de '+(fileLimit/1048576).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MB.';return;}form.set('file',file);}fileBusy=true;document.getElementById('file-send').disabled=true;document.getElementById('file-receive').disabled=true;fileMessage.textContent='Enviando solicitação…';try{await fileApi(action,{method:'POST',body:form});fileMessage.textContent='Solicitação enviada. Aguarde a autorização no computador.';document.getElementById('file-source').value='';}catch(e){fileMessage.textContent=plain(e.message);}finally{fileBusy=false;document.getElementById('file-send').disabled=false;document.getElementById('file-receive').disabled=false;loadFiles();}}
document.getElementById('file-send-form').addEventListener('submit',e=>{e.preventDefault();requestFile('file-send');});document.getElementById('file-receive').addEventListener('click',()=>requestFile('file-receive'));

const scheduleDialog=document.getElementById('support-schedules'),scheduleForm=document.getElementById('schedule-form'),scheduleMessage=document.getElementById('schedule-feedback'),scheduleList=document.getElementById('schedule-list'),scheduleRuns=document.getElementById('schedule-runs'),scheduleLabels=<?=json_encode(arc_support_schedule_actions(),JSON_UNESCAPED_UNICODE)?>;
let scheduleBusy=false;
function scheduleFields(){const mode=scheduleForm.elements.recurrence.value;document.querySelector('[data-schedule-days]').hidden=mode!=='weekdays';document.querySelector('[data-schedule-interval]').hidden=mode!=='interval';document.querySelector('[data-schedule-power]').hidden=!scheduleForm.elements.command.value.startsWith('power_');}
scheduleForm.elements.recurrence.addEventListener('change',scheduleFields);scheduleForm.elements.command.addEventListener('change',scheduleFields);scheduleFields();
const scheduleDate=value=>value?value.slice(8,10)+'/'+value.slice(5,7)+'/'+value.slice(0,4)+' '+value.slice(11,16):'Encerrado';
async function scheduleApi(action,data={}){return json(base+'api/support.php?action=schedule-'+action,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({network_id:network,agent_id:Number(document.getElementById('arc-agent-target').value),...data})});}
async function loadSchedules(){if(!scheduleDialog.open)return;try{const data=await scheduleApi('list');scheduleList.replaceChildren();for(const row of data.schedules){const item=document.createElement('article'),copy=document.createElement('div'),title=document.createElement('strong'),info=document.createElement('small');title.textContent=scheduleLabels[row.command_name]||'Serviço';const repeat=row.recurrence==='once'?'Uma vez':row.recurrence==='interval'?'A cada '+row.interval_minutes+' min':row.weekdays.split(',').map(d=>['','Seg','Ter','Qua','Qui','Sex','Sáb','Dom'][Number(d)]).join(', ');info.textContent=(!Number(row.enabled)?'Cancelado':row.next_run_at?'Próxima: '+scheduleDate(row.next_run_at):'Encerrado')+' · '+repeat+(row.ends_at?' · até '+scheduleDate(row.ends_at):'');copy.append(title,info);item.append(copy);if(Number(row.enabled)){const cancel=document.createElement('button');cancel.type='button';cancel.className='arc-icon-action';cancel.setAttribute('aria-label','Cancelar agendamento de '+title.textContent);cancel.title='Cancelar agendamento';cancel.innerHTML='<i class="fa fa-calendar-times-o" aria-hidden="true"></i>';cancel.addEventListener('click',async()=>{cancel.disabled=true;try{await scheduleApi('cancel',{id:row.id});scheduleMessage.textContent='Agendamento cancelado. Ações já iniciadas não são desfeitas.';await loadSchedules();}catch(e){scheduleMessage.textContent=plain(e.message);cancel.disabled=false;}});item.append(cancel);}scheduleList.append(item);}if(!data.schedules.length)scheduleList.textContent='Nenhum serviço agendado.';scheduleRuns.replaceChildren();const statuses={pending:'Na fila',running:'Em execução',completed:'Concluído',failed:'Não concluído',expired:'Não executado'};for(const run of data.runs){const item=document.createElement('article'),copy=document.createElement('div'),title=document.createElement('strong'),info=document.createElement('small');title.textContent=(scheduleLabels[run.command_name]||'Serviço')+' · '+scheduleDate(run.scheduled_for);info.textContent=run.task_status?statuses[run.task_status]||'Em andamento':plain(run.message);if(run.result_text)info.textContent+=' · '+plain(run.result_text);copy.append(title,info);item.append(copy);scheduleRuns.append(item);}if(!data.runs.length)scheduleRuns.textContent='Nenhuma execução ainda.';}catch(e){scheduleMessage.textContent=plain(e.message);}}
document.querySelector('[data-open-dialog="support-schedules"]').addEventListener('click',()=>setTimeout(loadSchedules,0));scheduleDialog.addEventListener('close',()=>{scheduleForm.elements.password.value='';scheduleForm.elements.confirmed.checked=false;});
scheduleForm.addEventListener('submit',async event=>{event.preventDefault();if(scheduleBusy)return;scheduleBusy=true;const submit=scheduleForm.querySelector('[type=submit]');submit.disabled=true;const data=Object.fromEntries(new FormData(scheduleForm));data.weekdays=[...scheduleForm.querySelectorAll('[name=weekdays]:checked')].map(x=>Number(x.value));data.confirmed=scheduleForm.elements.confirmed.checked;try{await scheduleApi('save',data);scheduleMessage.textContent='Serviço agendado.';scheduleForm.elements.password.value='';scheduleForm.elements.confirmed.checked=false;await loadSchedules();}catch(e){scheduleMessage.textContent=plain(e.message);}finally{scheduleBusy=false;submit.disabled=false;}});
setInterval(()=>{if(!document.hidden&&scheduleDialog.open&&!scheduleBusy)loadSchedules()},10000);

document.querySelectorAll('[data-tool-command]').forEach(button=>button.addEventListener('click',async()=>{if(busy)return;const agent=Number(document.getElementById('arc-agent-target').value);if(!agent)return;busy=true;button.disabled=true;facts.replaceChildren();document.getElementById('tool-title').textContent=button.querySelector('strong').textContent;state.textContent='Aguardando o computador…';dialog.showModal();try{const request=await json(base+'api/api.php?action=network-command',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({network_id:network,agent_id:agent,command:button.dataset.toolCommand})});const deadline=Date.now()+180000;let completedWait=0;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,1500));const result=await json(base+'api/api.php?action=network-tool-result&network_id='+network+'&agent_id='+agent+'&command_id='+request.command_id);if(result.result){state.textContent=plain(result.result.summary);details(result.result.details);feedback.textContent=state.textContent;return;}if(result.task.status==='completed'&&!result.result&&completedWait++<3)continue;if(['failed','expired','completed'].includes(result.task.status)){state.textContent=plain(result.task.result_text||'A verificação terminou.');feedback.textContent=state.textContent;return;}state.textContent=result.task.status==='running'?'O computador está verificando…':'Aguardando o computador responder…';}throw Error('O computador não respondeu a tempo. Confira se está conectado.');}catch(e){state.textContent=plain(e.message);feedback.textContent=state.textContent;}finally{busy=false;button.disabled=false;}}));})();
</script>
<?php require __DIR__.'/_rodape.php';?>
